import { test, expect } from '@playwright/test';

test.describe('Product List Display', () => {
  const BASE_URL = 'https://www.saucedemo.com';
  const USERNAME = 'standard_user';
  const PASSWORD = 'secret_sauce';

  test.beforeEach(async ({ page }) => {
    await page.goto(BASE_URL);

    // Login with standard_user credentials
    const usernameInput = page.getByLabel('Username');
    const passwordInput = page.getByLabel('Password');
    const loginButton = page.getByRole('button', { name: /login/i });

    await usernameInput.fill(USERNAME);
    await passwordInput.fill(PASSWORD);
    await loginButton.click();

    // Wait for inventory page to load
    await page.waitForURL('**/inventory.html');
  });

  test('should display exactly 6 product cards on inventory page', async ({ page }) => {
    const inventoryItems = page.locator('.inventory_item');

    const count = await inventoryItems.count();
    expect(count).toBe(6);
  });

  test('each product card should contain name and price elements with valid content', async ({ page }) => {
    const inventoryItems = page.locator('.inventory_item');

    const itemCount = await inventoryItems.count();
    expect(itemCount).toBe(6);

    for (let i = 0; i < itemCount; i++) {
      const item = inventoryItems.nth(i);

      // Verify name element exists and has non-empty text
      const nameElement = item.locator('.inventory_item_name');
      const nameText = await nameElement.textContent();
      expect(nameText).toBeTruthy();
      expect(nameText?.trim().length).toBeGreaterThan(0);

      // Verify price element exists and starts with '$'
      const priceElement = item.locator('.inventory_item_price');
      const priceText = await priceElement.textContent();
      expect(priceText).toBeTruthy();
      expect(priceText?.trim()).toMatch(/^\$/);
    }
  });

  test('all product cards should be visible and properly structured', async ({ page }) => {
    const inventoryItems = page.locator('.inventory_item');

    await expect(inventoryItems).toHaveCount(6);

    // Verify all items are visible
    for (let i = 0; i < 6; i++) {
      const item = inventoryItems.nth(i);
      await expect(item).toBeVisible();

      // Verify both name and price are visible within each card
      const nameElement = item.locator('.inventory_item_name');
      const priceElement = item.locator('.inventory_item_price');

      await expect(nameElement).toBeVisible();
      await expect(priceElement).toBeVisible();
    }
  });
});
